// Character classification tables used by the slugify library.
//
// The separator set below was determined empirically from the reference
// implementation: it is exactly ASCII whitespace (space, \t, \n, \r, \v, \f)
// plus all ASCII punctuation EXCEPT the backslash. Every other character
// (including all non-ASCII letters, symbols and Unicode whitespace such as
// U+00A0 or U+2003) is preserved verbatim in the output.

export const ASCII_WHITESPACE = ' \t\n\r\v\f';

// Same membership as Python's string.punctuation with '\\' removed.
export const ASCII_PUNCTUATION_EXCEPT_BACKSLASH =
  '!"#$%&\'()*+,-./:;<=>?@[]^_`{|}~';

export const SEPARATOR_CHARS = new Set(
  ASCII_WHITESPACE + ASCII_PUNCTUATION_EXCEPT_BACKSLASH
);

export function isSeparator(ch) {
  return SEPARATOR_CHARS.has(ch);
}

// Reimplementation of boltons.strutils.slugify (default options only:
// delim='_', lower=True, ascii=False), matching the observed behavior of
// the reference executable character for character.
//
// Observed semantics:
//   1. The text is lowercased with full Unicode default case conversion
//      (equivalent to Python's str.lower()).
//   2. Maximal runs of separator characters (see charsets.mjs) act as word
//      boundaries; words are joined with the delimiter.
//   3. Leading and trailing separator runs disappear (no empty words).
//   4. If the input is non-empty but contains no word characters at all,
//      the result is a single delimiter. Empty input yields empty output.

import { isSeparator } from './charsets.mjs';

export function slugify(text, delim = '_', lower = true) {
  let s = String(text);
  if (lower) {
    // String.prototype.toLowerCase implements the same Unicode default
    // case conversion as Python's str.lower() (including final sigma).
    s = s.toLowerCase();
  }

  const words = [];
  let current = '';
  // for..of iterates by code point, matching Python's per-character loop.
  for (const ch of s) {
    if (isSeparator(ch)) {
      if (current !== '') {
        words.push(current);
        current = '';
      }
    } else {
      current += ch;
    }
  }
  if (current !== '') {
    words.push(current);
  }

  const joined = words.join(delim);
  if (joined === '' && s !== '') {
    return delim;
  }
  return joined;
}

// Minimal, dependency-free reimplementation of the slice of Python's
// argparse needed by the entry script: a parser with the automatic
// -h/--help option plus declared long options, GNU-style "--opt value" and
// "--opt=value" forms, unambiguous prefix abbreviation, argparse-compatible
// usage/help/error text, and exit codes (0 for --help, 2 for errors).

// Matches argparse's _negative_number_matcher: such tokens are treated as
// values rather than options.
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  return (
    token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER_RE.test(token)
  );
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.options = [
      {
        names: ['-h', '--help'],
        dest: 'help',
        takesValue: false,
        help: 'show this help message and exit',
        invocation: '-h, --help',
      },
    ];
  }

  addOption(names, { dest, metavar, required = false } = {}) {
    const primary = names[names.length - 1];
    this.options.push({
      names,
      dest: dest || primary.replace(/^--?/, '').replace(/-/g, '_'),
      takesValue: true,
      metavar: metavar || dest?.toUpperCase() || 'VALUE',
      required,
      invocation: `${primary} ${metavar}`,
    });
  }

  formatUsage() {
    const parts = this.options.map((o) =>
      o.required ? o.invocation : `[${o.invocation}]`
    );
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  formatHelp() {
    const usage = this.formatUsage();
    const width = Math.max(...this.options.map((o) => o.invocation.length));
    const lines = this.options.map((o) => {
      const head = `  ${o.invocation}`;
      return o.help ? head.padEnd(2 + width + 2) + o.help : head;
    });
    return `${usage}\n\noptions:\n${lines.join('\n')}`;
  }

  error(message) {
    process.stderr.write(`${this.formatUsage()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    process.stdout.write(`${this.formatHelp()}\n`);
    process.exit(0);
  }

  resolveLong(name) {
    const matches = this.options.filter((o) => o.names.includes(name));
    if (matches.length === 1) return matches[0];
    // Unambiguous prefix abbreviation (argparse's allow_abbrev=True).
    const prefixed = this.options.filter((o) =>
      o.names.some((n) => n.startsWith('--') && n.startsWith(name))
    );
    if (prefixed.length === 1) return prefixed[0];
    if (prefixed.length > 1) {
      const candidates = prefixed
        .map((o) => o.names.find((n) => n.startsWith(name)))
        .join(', ');
      this.error(`ambiguous option: ${name} could match ${candidates}`);
    }
    return null;
  }

  parse(argv) {
    const values = {};
    const extras = [];
    let optionsEnded = false;
    let i = 0;

    while (i < argv.length) {
      const token = argv[i];

      if (!optionsEnded && token === '--') {
        optionsEnded = true;
        i += 1;
        continue;
      }

      if (!optionsEnded && token.startsWith('--')) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const inlineValue = eq === -1 ? null : token.slice(eq + 1);
        const opt = this.resolveLong(name);
        if (!opt) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (!opt.takesValue) {
          if (inlineValue !== null) {
            this.error(`argument ${opt.invocation}: ignored explicit argument '${inlineValue}'`);
          }
          this.printHelp();
        }
        if (inlineValue !== null) {
          values[opt.dest] = inlineValue;
          i += 1;
          continue;
        }
        const next = argv[i + 1];
        if (next === undefined || (looksLikeOption(next) && next !== '-')) {
          this.error(`argument ${opt.invocation}: expected one argument`);
        }
        values[opt.dest] = next;
        i += 2;
        continue;
      }

      if (!optionsEnded && looksLikeOption(token)) {
        if (token === '-h') {
          this.printHelp();
        }
        extras.push(token);
        i += 1;
        continue;
      }

      extras.push(token);
      i += 1;
    }

    const missing = this.options.filter((o) => o.required && !(o.dest in values));
    if (missing.length > 0) {
      const names = missing.map((o) => o.names[o.names.length - 1]).join(', ');
      this.error(`the following arguments are required: ${names}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

// Entry point — ESM port of test4.py:
//
//   import argparse
//   from boltons.strutils import slugify
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
//   args = parser.parse_args()
//
//   result = slugify(args.a)
//   print(result)

import { basename } from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import { slugify } from './lib/slugify.mjs';

// argparse derives prog from os.path.basename(sys.argv[0]); the Node
// equivalent of sys.argv[0] for a script is process.argv[1].
const prog = basename(process.argv[1] || 'test4.mjs');

const parser = new ArgumentParser(prog);
parser.addOption(['--a'], { dest: 'a', metavar: 'A', required: true });

const args = parser.parse(process.argv.slice(2));

const result = slugify(args.a);
console.log(result);

